#include <stdio.h>

int main(void) {
    int N;
    double D;
    scanf("%d %lf", &N, &D);

    double P[1005], C[1005];
    for (int i = 0; i < N; ++i) {
        scanf("%lf %lf", &P[i], &C[i]);
    }

    double dp[1005];
    dp[0] = 0.0;

    for (int i = 1; i < N; ++i) {
        double best = 1e100;
        for (int j = 0; j < i; ++j) {
            double dist = P[i] - P[j];
            double cost = dp[j] + (dist * dist) / C[j];
            if (cost < best) best = cost;
        }
        dp[i] = best;
    }

    double ans = 1e100;
    for (int i = 0; i < N; ++i) {
        double dist = D - P[i];
        double cost = dp[i] + (dist * dist) / C[i];
        if (cost < ans) ans = cost;
    }

    printf("%.3f\n", ans);
    return 0;
}
